-- =========================================================
-- Sanatan API — Gita chapters metadata (real data)
-- Run AFTER schema.sql in Supabase SQL Editor.
-- Creates public.gita_chapters and upserts 18 rows from
-- chapters_summary.json. Safe to re-run.
-- =========================================================

create table if not exists public.gita_chapters (
  chapter_number int primary key,
  eng_name      text not null,
  sanskrit_name text not null,
  meaning_en    text,
  meaning_hi    text,
  summary_en    text,
  summary_hi    text,
  verses_count  int not null
);

alter table public.gita_chapters enable row level security;
drop policy if exists "gita chapters public read" on public.gita_chapters;
create policy "gita chapters public read" on public.gita_chapters for select using (true);

insert into public.gita_chapters
  (chapter_number, eng_name, sanskrit_name, meaning_en, meaning_hi, summary_en, summary_hi, verses_count)
values
  (1, 'Arjuna Visada Yoga', 'अर्जुन विषाद योग', 'Arjuna''s Dilemma', 'अर्जुन का विषाद', 'At the battlefield of Kurukshetra, Arjuna sees his grandfathers, teachers, uncles, brothers, sons and friends arrayed on the opposing side. Overcome by grief and pity, his mind bewildered, he lays down his bow and refuses to fight.', 'कुरुक्षेत्र के युद्धभूमि में अर्जुन को अपने दादा, गुरुजन, चाचा, भाई, पुत्र और मित्र विपक्षी सेना में खड़े दिखते हैं। शोक और करुणा से व्याप्त होकर, मन भ्रमित हो जाने पर वह अपना धनुष रख देता है और युद्ध करने से मना कर देता है।', 47),
  (2, 'Sankhya Yoga', 'सांख्य योग', 'Transcendental Knowledge', 'अध्यात्मिक ज्ञान', 'Chapter 2 summarizes the entire Bhagavad Gita. Arjuna surrenders to Krishna as a disciple, seeking spiritual instruction to overcome his grief and confusion. Krishna teaches the eternality of the soul, the distinction between the body and the self, and the principle of performing one''s duty without attachment to results.', 'दूसरा अध्याय सम्पूर्ण भगवद्गीता का सार है। अपने शोक और मोह को दूर करने के लिए अर्जुन कृष्ण को गुरु मानकर शरण लेता है और उनसे आध्यात्मिक उपदेश चाहता है। कृष्ण आत्मा की अमरता, शरीर और आत्मा में भेद, तथा फल की इच्छा से रहित होकर कर्तव्य करने का उपदेश देते हैं।', 72),
  (3, 'Karma Yoga', 'कर्म योग', 'Path of Action', 'कर्म मार्ग', 'Krishna explains that no one can remain without action, and that inaction is not the path to liberation. He teaches selfless action performed as duty, without attachment to outcomes and without desire for fruit, which frees one from the bondage of karma.', 'कृष्ण समझाते हैं कि कोई भी प्राणी बिना कर्म किए नहीं रह सकता और कर्म न करना मोक्ष का मार्ग नहीं है। वे फल की आसक्ति और इच्छा से रहित, कर्तव्य रूप में किए गए निष्काम कर्म का उपदेश देते हैं, जो मनुष्य को कर्मबंधन से मुक्त कर देता है।', 43),
  (4, 'Jnana Karma Sanyasa Yoga', 'ज्ञान कर्म संन्यास योग', 'Knowledge and Renunciation of Action', 'ज्ञान और कर्म संन्यास', 'Krishna reveals his divine birth and purpose — whenever dharma declines, he manifests himself to protect the righteous. He explains that action performed without attachment does not bind, that knowledge purifies and destroys ignorance, and that the wise act in the spirit of sacrifice.', 'कृष्ण अपने दिव्य जन्म और उद्देश्य का रहस्य खोलते हैं — जब-जब धर्म की हानि होती है, वे धार्मिकों की रक्षा के लिए स्वयं प्रकट होते हैं। वे बताते हैं कि आसक्ति रहित किया गया कर्म बांधता नहीं, ज्ञान शुद्ध करता है और अज्ञान का नाश करता है, तथा ज्ञानी यज्ञभाव से कर्म करते हैं।', 42),
  (5, 'Karma Sanyasa Yoga', 'कर्म संन्यास योग', 'Path of Renunciation', 'संन्यास का मार्ग', 'Krishna clarifies that both renunciation and selfless action lead to liberation, but karma yoga is superior. The one who sees inaction in action and action in inaction is truly wise. The karma yogi, untouched by sin and free from duality, attains the eternal peace of Brahman.', 'कृष्ण स्पष्ट करते हैं कि संन्यास और निष्काम कर्म — दोनों से मोक्ष मिलता है, परंतु कर्म योग श्रेष्ठ है। कर्म में अकर्म और अकर्म में कर्म देखने वाला ही वास्तव में पंडित है। निष्काम कर्मी पाप से अलिप्त रहकर द्वंद्व से रहित हो ब्रह्म की शाश्वत शांति पाता है।', 29),
  (6, 'Dhyana Yoga', 'ध्यान योग', 'Path of Meditation', 'ध्यान का मार्ग', 'Krishna describes the practice of meditation — sitting posture, withdrawal of the senses, controlling the restless mind through practice and detachment, and moderation in eating, sleeping and activity. The yogi who has conquered the mind sees the self in all beings, and Krishna declares such a yogi to be the highest.', 'कृष्ण ध्यान की विधि बताते हैं — आसन, इंद्रियों का निग्रह, अभ्यास और वैराग्य से चंचल मन का संयम, तथा आहार, निद्रा और व्यवहार में संयम। जिस योगी ने मन को जीत लिया, वह सभी प्राणियों में आत्मा देखता है, और कृष्ण ऐसे योगी को ही श्रेष्ठ घोषित करते हैं।', 47),
  (7, 'Jnana Vijnana Yoga', 'ज्ञान विज्ञान योग', 'Self-Knowledge and Enlightenment', 'आत्मज्ञान और आत्म-साक्षात्कार', 'Krishna describes his two natures — the lower material nature and the higher spiritual nature that sustains all beings. Overcome by his divine illusion (maya), most beings fail to recognize him, but those who surrender and worship him with devotion attain him, knowing him as the source of all.', 'कृष्ण अपनी दो प्रकृतियों का वर्णन करते हैं — निम्न जड़ प्रकृति और वह परा प्रकृति जिससे समस्त प्राणी धारित हैं। अपनी दिव्य माया से विवेक खोकर अधिकांश प्राणी उन्हें नहीं पहचानते, परंतु जो शरण लेकर भक्ति से उनकी उपासना करते हैं, वे सबके आधार उन्हीं को प्राप्त करते हैं।', 30),
  (8, 'Aksara Brahma Yoga', 'अक्षर ब्रह्म योग', 'Path of the Eternal God', 'अविनाशी ब्रह्म का मार्ग', 'Krishna defines key terms — Brahman, the individual soul, action, the material, the divine and the sacrifice — and declares that whatever one remembers at the time of death, that one attains. He describes the two paths after death — the path of light leading to liberation and the path of darkness leading to rebirth.', 'कृष्ण ब्रह्म, अध्यात्म, कर्म, अधिभूत, अधिदैव और अधियज्ञ — इन शब्दों का अर्थ बताते हुए कहते हैं कि अंत समय में जिसका स्मरण किया जाता है, वही प्राप्त होता है। वे मृत्यु के बाद के दो मार्ग बताते हैं — मोक्ष देने वाला ज्योतिर्मय पथ और पुनर्जन्म की ओर ले जाने वाला अंधकारमय पथ।', 28),
  (9, 'Raja Vidya Raja Guhya Yoga', 'राज विद्या राज गुह्य योग', 'King of Sciences and King of Secrets', 'विद्याओं का राजा और रहस्यों का राजा', 'Krishna reveals the supreme secret: all beings rest in him and are sustained by his divine energy, yet he remains unattached and impartial. Whoever worships him with devotion comes to him — even the greatest sinner can cross over, for those who take refuge in him attain the supreme goal.', 'कृष्ण परम रहस्य बताते हैं — समस्त प्राणी उन्हीं में स्थित हैं और उनकी दिव्य शक्ति से धारित हैं, फिर भी वे निर्लिप्त और समदृष्टि वाले हैं। जो भी भक्ति से उनकी उपासना करता है, वह उन्हें प्राप्त होता है — महापापी भी उनकी शरण लेकर पार हो जाता है।', 34),
  (10, 'Vibhuti Yoga', 'विभूति योग', 'The Infinite Glories of the Supreme', 'परमात्मा की अनंत महिमा', 'Krishna describes his divine manifestations — the best of everything in creation expresses his glory. He is the beginning, middle and end of all beings, and wherever one finds excellence, strength or beauty, one should see his splendour.', 'कृष्ण अपनी दिव्य विभूतियों का वर्णन करते हैं — सृष्टि की हर वस्तु में श्रेष्ठतम उनकी ही महिमा का द्योतक है। वे ही सब प्राणियों का आदि, मध्य और अंत हैं; जहाँ कहीं भी उत्कृष्टता, बल या सौंदर्य दिखे, वहाँ उनके ही तेज को देखना चाहिए।', 42),
  (11, 'Vishwarupa Darshana Yoga', 'विश्वरूप दर्शन योग', 'The Vision of the Cosmic Form', 'विराट रूप का दर्शन', 'Krishna grants Arjuna divine eyes to see his universal form — infinite, blazing, containing all gods and all worlds. Seeing time as the destroyer of all beings, Arjuna trembles with awe and offers prayers. Krishna then reassumes his gentle human form and tells Arjuna that only devotion can perceive him thus.', 'कृष्ण अर्जुन को दिव्य दृष्टि देकर अपना विराट रूप दिखाते हैं — अनंत, तेजस्वी, जिसमें समस्त देवता और लोक समाहित हैं। सबका नाश करने वाले काल को देखकर अर्जुन कांपने लगता है और स्तुति करता है। फिर कृष्ण अपना सौम्य मानव रूप धारण कर बताते हैं कि केवल अनन्य भक्ति से ही उन्हें ऐसे देखा जा सकता है।', 55),
  (12, 'Bhakti Yoga', 'भक्ति योग', 'The Path of Devotion', 'भक्ति मार्ग', 'Krishna says that worshipping him with steadfast devotion is superior to pursuing the unmanifest absolute. He then describes the qualities of his beloved devotee — free from hatred, friendly and compassionate, without ego and possessiveness, equal in pleasure and pain, forgiving, ever content and devoted.', 'कृष्ण कहते हैं कि अव्यक्त (निराकार) ब्रह्म की उपासना की अपेक्षा साकार रूप में अनन्य भक्ति से उनकी उपासना श्रेष्ठ है। फिर वे अपने प्रिय भक्त के गुण बताते हैं — जो द्वेष रहित, मित्रभावयुक्त, करुणामय, अहंकार और ममता से रहित, सुख-दुख में सम, क्षमाशील, सदा संतुष्ट और भक्तियुक्त है।', 20),
  (13, 'Kshetra Kshetrajna Vibhaga Yoga', 'क्षेत्र क्षेत्रज्ञ विभाग योग', 'The Field and the Knower of the Field', 'क्षेत्र और क्षेत्रज्ञ', 'Krishna distinguishes between the field (the body and nature) and the knower of the field (the soul), declaring himself the knower in all fields. He explains prakriti and purusha, lists the qualities of true knowledge such as humility and non-attachment, and describes the supreme self beyond both.', 'कृष्ण क्षेत्र (शरीर/प्रकृति) और क्षेत्रज्ञ (आत्मा) में भेद बताते हुए कहते हैं कि सब क्षेत्रों में क्षेत्रज्ञ वे स्वयं हैं। वे प्रकृति और पुरुष का स्वरूप समझाते हैं, अमानित्व और अनासक्ति जैसे ज्ञान के गुण गिनाते हैं तथा इन दोनों से परे परमात्मा का वर्णन करते हैं।', 35),
  (14, 'Gunatraya Vibhaga Yoga', 'गुणत्रय विभाग योग', 'The Three Gunas of Material Nature', 'प्रकृति के तीन गुण', 'Krishna explains the three gunas that spring from prakriti and bind the soul — sattva binds through attachment to happiness, rajas through desire and action, and tamas through negligence and laziness. One who transcends the three gunas attains immortality; Krishna invites such a person to become his devotee and take refuge in him.', 'कृष्ण प्रकृति से उत्पन्न तीन गुणों की व्याख्या करते हैं जो आत्मा को बांधते हैं — सत्त्व सुख की आसक्ति से, रजस इच्छा और कर्म से, तथा तमस प्रमाद और आलस्य से बांधता है। तीनों गुणों से परे होकर मनुष्य अमरता पाता है; कृष्ण ऐसे पुरुष को अपना भक्त बनकर शरण लेने को कहते हैं।', 27),
  (15, 'Purushottama Yoga', 'पुरुषोत्तम योग', 'The Supreme Divine Person', 'परम पुरुषोत्तम', 'Krishna describes creation as an eternal ashvattha tree with roots above and branches below, which must be cut by detachment. The individual souls in this world are his eternal fragments. Beyond the perishable and the imperishable, he is the Supreme Person — knowing whom, one attains liberation.', 'कृष्ण सृष्टि को ऊपर जड़ और नीचे डालियों वाले अनादि अश्वत्थ वृक्ष के समान बताते हैं, जिसे वैराग्य के शस्त्र से काटना चाहिए। संसार के समस्त जीव उनके अंश हैं। क्षर और अक्षर — दोनों से परे वे ही पुरुषोत्तम हैं; उन्हें जानकर मनुष्य मुक्त हो जाता है।', 20),
  (16, 'Daivasura Sampad Vibhaga Yoga', 'दैवासुर सम्पद् विभाग योग', 'The Divine and Demoniac Natures', 'दैवी और आसुरी स्वभाव', 'Krishna contrasts the divine nature — fearlessness, purity of heart, truthfulness, self-restraint and non-violence — with the demoniac nature of arrogance, anger, harshness and ignorance. Those of demoniac nature, heedless of scripture and driven by desire, sink into lower births, while the divine nature leads to liberation.', 'कृष्ण दैवी स्वभाव — अभय, सत्त्वशुद्धि, सत्य, इंद्रिय-संयम और अहिंसा — की तुलना आसुरी स्वभाव — अहंकार, क्रोध, कठोरता और अज्ञान — से करते हैं। शास्त्र की अवहेला कर इच्छाओं के वशीभूत आसुरी स्वभाव वाले निम्न योनियों में गिरते हैं, जबकि दैवी स्वभाव मोक्ष की ओर ले जाता है।', 24),
  (17, 'Sraddhatraya Vibhaga Yoga', 'श्रद्धात्रय विभाग योग', 'The Three Divisions of Faith', 'श्रद्धा के तीन भेद', 'Krishna teaches that faith differs according to one''s nature — sattvic, rajasic or tamasic — and classifies food, charity, austerity and worship accordingly. He concludes by explaining the threefold meaning of Om Tat Sat, which marks all acts of sacrifice, charity and austerity.', 'कृष्ण बताते हैं कि श्रद्धा स्वभाव के अनुसार सात्त्विक, राजसिक या तामसिक होती है, और उसी के अनुसार वे आहार, दान, तप और उपासना का वर्गीकरण करते हैं। अंत में वे ॐ तत् सत् के त्रिविध अर्थ समझाते हैं, जो समस्त यज्ञ, दान और तप का द्योतक है।', 28),
  (18, 'Moksha Sanyasa Yoga', 'मोक्ष संन्यास योग', 'Liberation through Renunciation', 'संन्यास द्वारा मोक्ष', 'The concluding chapter summarizes the entire Gita — the distinction between renunciation and relinquishment, knowledge, action and the three gunas. Krishna finally delivers his supreme instruction: abandon all dharmas and surrender to him alone, and he will free one from all sins. Better one''s own duty imperfectly done than another''s done well.', 'अंतिम अध्याय सम्पूर्ण गीता का सार है — संन्यास और त्याग में भेद, ज्ञान, कर्म और तीनों गुणों का विवेचन। अंत में कृष्ण अपना परम उपदेश देते हैं — सर्वधर्मों का त्याग कर केवल मेरी शरण लो, मैं तुम्हें सब पापों से मुक्त कर दूंगा। अपना (अपूर्ण) कर्तव्य दूसरे के धर्म से किए गए शुद्ध कर्तव्य से श्रेष्ठ है।', 78)
on conflict (chapter_number) do update set
  eng_name      = excluded.eng_name,
  sanskrit_name = excluded.sanskrit_name,
  meaning_en    = excluded.meaning_en,
  meaning_hi    = excluded.meaning_hi,
  summary_en    = excluded.summary_en,
  summary_hi    = excluded.summary_hi,
  verses_count  = excluded.verses_count;
